@if($campaigns->isEmpty())<div class="empty"><span aria-hidden="true">↗</span><h3>No campaigns to show</h3><p>Campaigns belonging to your account will appear here.</p></div>@else<div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Status</th><th>Delivery</th><th>Schedule</th></tr></thead><tbody>@foreach($campaigns as $campaign)<tr><td><strong>{{ $campaign->name }}</strong><small>Created {{ $campaign->created_at->format('d M Y') }}</small></td><td><span class="pill {{ in_array($campaign->status, ['ready','running']) ? 'good' : '' }}">{{ ucfirst($campaign->status) }}</span>@if($campaign->status === 'completed')<small>Execution ended; delivery may have failed.</small>@endif</td><td>{{ number_format($campaign->delivered_count) }} / {{ number_format($campaign->audience_count) }}<small>Recipients with completed playback</small></td><td>@if($campaign->scheduled_at){{ $campaign->scheduled_at->format('d M Y, H:i') }}<small>UTC</small>@else<span class="muted">Unscheduled</span>@endif</td></tr>@endforeach</tbody></table></div>@endif
